using System;
using UnityEngine;
using Pvp.Map;
using Pvp.Network;
using Pvp.Driving;
using Pvp.Traffic;
using Pvp.Competition;
namespace Pvp.Tests.EditMode {
public static class PvpExpandedTests {
 static int checks;static void Check(bool ok,string reason){checks++;if(!ok)throw new Exception("PVP_EXPANDED: "+reason);}
 public static void RunAll(){PvpSoloBotTests.RunAll();Run();ServiceTrip();}
 public static void Run(){var definition=PvpMapDefinition.CreateExpanded();try{
  var map=new PvpMapRuntime(definition);Check(map.IsExpanded&&map.Stops.Count==8&&map.Services.Count==2&&map.NpcPaths.Count==6&&map.PedestrianPaths.Count==4,"expanded content counts");Check(map.BoundsMax.x-map.BoundsMin.x>=520&&map.BoundsMax.z-map.BoundsMin.z>=440,"larger own map");float shortest=float.MaxValue,longest=0;
  for(int a=0;a<8;a++)for(int b=0;b<8;b++)if(a!=b){var route=PvpRoutePlanner.FindRoute(map,map.Stops[a].Node,map.Stops[b].Node);Check(route.Found,"all stop pairs reachable "+a+">"+b);shortest=Mathf.Min(shortest,route.Distance);longest=Mathf.Max(longest,route.Distance);}Check(longest>800&&longest>shortest*3,"short and long transport alternatives");
  float ring=0;foreach(int e in map.NpcPaths[2].Edges)ring+=Vector3.Distance(map.Nodes[map.Connections[e].From],map.Nodes[map.Connections[e].To]);Check(Mathf.Abs(ring-1760)<.01f,"1760m outer circuit");
  string hash=map.MapHash;var zone=definition.SignalZones[2];zone.OffsetTicks++;definition.SignalZones[2]=zone;Check(new PvpMapRuntime(definition).MapHash!=hash&&map.SignalZones[2].OffsetTicks!=zone.OffsetTicks,"signal config hash and source isolation");zone.OffsetTicks--;definition.SignalZones[2]=zone;definition.NpcPaths[2].Speed=9;Check(new PvpMapRuntime(definition).MapHash!=hash&&map.NpcPaths[2].Speed==8,"nested NPC config clone/hash");definition.NpcPaths[2].Speed=8;var mutable=map.NpcPaths[2];mutable.Edges[0]=0;Check(map.NpcPaths[2].Edges[0]==18,"published NPC definition immutable");
  var invalid=definition.SignalZones[2];invalid.RightTurnEdge=0;definition.SignalZones[2]=invalid;bool rejected=false;try{new PvpMapRuntime(definition);}catch(ArgumentException){rejected=true;}Check(rejected,"invalid signal connection rejected");definition.SignalZones[2]=zone;
  int routes=0;for(int spawn=0;spawn<4;spawn++)for(int goal=0;goal<8;goal++){var motor=new PvpNetworkMotor(map,spawn);var pilot=new PvpDrivingPilot(map);int tick=0;for(;tick<30000&&!pilot.Arrived(motor.Capture(),goal);tick++)motor.Step(pilot.Input(motor.Capture(),goal,tick),tick);Check(pilot.Arrived(motor.Capture(),goal)&&motor.BoundaryStops==0,"input path "+spawn+">"+goal+" ticks="+tick+" edge="+motor.Capture().Edge+" pos="+motor.Capture().State.Position+" boundary="+motor.BoundaryStops);routes++;}
  for(int goal=4;goal<8;goal++){var motor=new PvpNetworkMotor(map,0,true);var pilot=new PvpDrivingPilot(map);var traffic=new PvpNpcAuthority(map);var ledger=new PvpScoreLedger();var law=new Pvp.Rules.PvpRuleAuthority(map,"expanded-route",(p,id,rev,amount,t)=>ledger.ApplyIncident(p,id,rev,amount,t));int tick=1;
   for(;tick<30000&&!pilot.Arrived(motor.Capture(),goal);tick++){var before=motor.Capture();before.Connected=true;before.Tick=tick;traffic.Advance(tick,new[]{before});var shared=traffic.Snapshot();motor.ObserveTraffic(shared);pilot.ObserveTraffic(shared);motor.Step(pilot.Input(before,goal,tick),tick);var after=motor.Capture();after.Connected=true;law.Observe(0,before,after,motor.LastMotion,shared,true);}
   Check(pilot.Arrived(motor.Capture(),goal)&&motor.BoundaryStops==0,"shared traffic outer route goal="+goal+" tick="+tick+" pos="+motor.Capture().State.Position);Check(ledger.Read(0).Penalty==0,"lawful expanded route goal="+goal+" penalty="+ledger.Read(0).Penalty);Debug.Log("PVP_EXPANDED_ROUTE goal="+goal+" seconds="+(tick*.02f)+" distance="+motor.TravelDistance);
  }
  Services(map);TranslatedMap(definition);Debug.Log("PVP_EXPANDED_MODEL_OK checks="+checks+" inputRoutes="+routes+" minRoute="+shortest+" maxRoute="+longest+" outerRing="+ring);
 }finally{UnityEngine.Object.DestroyImmediate(definition);}}
 static void Services(PvpMapRuntime map){var config=new PvpSessionConfig{PlayerCount=2,MatchDurationSeconds=600,FinishGraceSeconds=10,RulesVersion="expanded-service-test"}.Freeze("services",map.MapHash);var round=new PvpRoundController(config,1);var ledger=new PvpScoreLedger();bool at=false;var services=new PvpServiceAuthority(map,round,ledger,(p,s)=>at,p=>10);int tick=0;
  for(int t=1;t<=750;t++){tick=t;round.Advance(t);services.Observe(0,new PvpDriveSnapshot{Tick=t,Connected=true,State=new PvpVehicleState{Position=Vector3.right*t*.4f,Speed=20}},true);}Check(services.Snapshot()[0].Fuel<95,"fuel from observed travel");string reason;Check(!services.Begin(0,map.Services[0].Id,"wrong-location",tick,out reason),"service requires correct bay");at=true;Check(services.Begin(0,map.Services[0].Id,"cancelled",tick,out reason)&&!services.CanDrive(0),"service blocks only its participant");Check(services.CanDrive(1),"other participant can drive");services.Cancel(0);Check(ledger.Read(0).ServiceExpenses==0,"cancel costs nothing");Check(services.Begin(0,map.Services[0].Id,"paid-once",tick,out reason),"retry after cancel");
  for(int t=tick+1;t<=tick+251;t++){round.Advance(t);services.Advance(t);}Check(services.Snapshot()[0].Fuel==100&&ledger.Read(0).ServiceExpenses==2&&services.CanDrive(0),"refill completes once at deadline");Check(!ledger.DebitService(0,"paid-once",2,round.Tick),"duplicate service debit idempotent");ledger.Complete(0,"after-service",1000,round.Tick);Check(ledger.Read(0).Bonus==1&&ledger.Read(0).Penalty==0&&ledger.Read(0).Score==9,"service separate from violation/safety");
  var closed=new PvpRoundController(new PvpSessionConfig{PlayerCount=2,MatchDurationSeconds=20,FinishGraceSeconds=0,RulesVersion="deadline"}.Freeze("closed",map.MapHash),1);var shortService=new PvpServiceAuthority(map,closed,new PvpScoreLedger(),(p,s)=>true,p=>10);for(int t=1;t<=750;t++){closed.Advance(t);shortService.Observe(0,new PvpDriveSnapshot{Tick=t,State=new PvpVehicleState{Position=Vector3.right*t*.4f}},true);}closed.Advance(999);Check(!shortService.Begin(0,"roadside","early-support",999,out reason),"support cannot bypass fuel condition");Check(!shortService.Begin(0,map.Services[0].Id,"too-late",999,out reason),"no chargeable service past final deadline");
 }
 static void TranslatedMap(PvpMapDefinition source){var shifted=UnityEngine.Object.Instantiate(source);try{var shift=new Vector3(350,0,280);for(int i=0;i<shifted.Nodes.Length;i++)shifted.Nodes[i]+=shift;for(int i=0;i<shifted.Stops.Length;i++){var stop=shifted.Stops[i];stop.Position+=shift;shifted.Stops[i]=stop;}for(int i=0;i<shifted.PedestrianPaths.Length;i++){var p=shifted.PedestrianPaths[i];p.From+=shift;p.To+=shift;shifted.PedestrianPaths[i]=p;}var obstacle=shifted.Obstacle;obstacle.From+=shift;obstacle.To+=shift;shifted.Obstacle=obstacle;var translated=new PvpMapRuntime(shifted);var traffic=new PvpNpcAuthority(translated);traffic.Advance(100,null);Check(traffic.Snapshot().Npcs[0].Position.x>200,"NPC data independent of original coordinates");var zone=translated.SignalZones[2];int tick=1;while(zone.Phase(tick)==0)tick++;var before=new PvpDriveSnapshot{Edge=zone.ApproachEdge,Connected=true,State=new PvpVehicleState{Position=translated.Position(new PvpRoadPosition(zone.ApproachEdge,zone.StopFraction-.001f)),Speed=5,YawDegrees=90}};var after=before;after.State.Position=translated.Position(new PvpRoadPosition(zone.ApproachEdge,zone.StopFraction+.001f));var scores=new PvpScoreLedger();var rules=new Pvp.Rules.PvpRuleAuthority(translated,"translated",(p,id,rev,amount,t)=>scores.ApplyIncident(p,id,rev,amount,t));rules.Observe(0,before,after,new Pvp.Rules.PvpMotionTrace{Tick=tick,Applied=true,Attempted=after.State.Position},traffic.Snapshot(),true);Check(scores.Read(0).Penalty==2,"translated authored signal stop line");}finally{UnityEngine.Object.DestroyImmediate(shifted);}}
 public static void ServiceTrip(){var d=PvpMapDefinition.CreateExpanded();try{var map=new PvpMapRuntime(d);var settings=new PvpSessionConfig{PlayerCount=2,MatchDurationSeconds=240,FinishGraceSeconds=15,RulesVersion="continuous-service"}.Freeze("continuous-service",map.MapHash);var a=new PvpPassengerAuthority(map,settings,150,2);var motors=new[]{new PvpNetworkMotor(map,0,true),new PvpNetworkMotor(map,1,true)};var bots=new[]{new PvpTaxiBot(map,0),new PvpTaxiBot(map,1)};var pilot=new PvpDrivingPilot(map);var traffic=new PvpNpcAuthority(map);var law=new Pvp.Rules.PvpRuleAuthority(map,"service-trip",(p,id,rev,amount,t)=>a.ApplyIncident(p,id,rev,amount,t));var world=a.Snapshot();var shared=PvpTrafficAuthority.At(map,0);bool cancel=false,done=false;int cancelTick=0,request=0;
  for(int tick=1;tick<=a.Round.FinalEndTick;tick++){a.Round.Advance(tick);var before=new PvpDriveSnapshot[2];for(int p=0;p<2;p++){before[p]=motors[p].Capture();before[p].Connected=true;before[p].Tick=tick;}traffic.Advance(tick,before);var current=traffic.Snapshot();
   for(int p=0;p<2;p++){var input=new PvpVehicleInput(0,1,0);PvpPassengerCommand? command=null;if(p==0){var state=world.Services[0];if(state.Status!=null&&state.Status.StartsWith("주유 완료"))done=true;
     if(world.Scores[0].Completed==0||done){var decision=bots[0].StepWithServices(world,shared,before[0]);input=decision.Input;command=decision.Command;}
     else if(state.Busy){if(!cancel&&tick>=state.BusyUntilTick-150){cancel=true;cancelTick=tick;command=new PvpPassengerCommand{MatchId=world.MatchId,RequestId="service-test-"+(++request),PassengerId="cancel",Kind=5};}}
     else if(!cancel||tick-cancelTick>=15){var facility=map.Services[0];pilot.ObserveTraffic(shared);input=pilot.Input(before[0],facility.StopIndex,tick);if(tick%15==0&&pilot.Arrived(before[0],facility.StopIndex))command=new PvpPassengerCommand{MatchId=world.MatchId,RequestId="service-test-"+(++request),PassengerId=facility.Id,Kind=3};}
    }else{var decision=bots[p].StepWithServices(world,shared,before[p]);input=decision.Input;command=decision.Command;}
    motors[p].ObserveTraffic(current);bool drive=a.Round.CanComplete&&a.Services.CanDrive(p);if(drive)motors[p].Step(input,tick);else{var pose=motors[p].Capture();pose.State.Speed=0;motors[p].Restore(pose);}var after=motors[p].Capture();after.Connected=true;after.Tick=tick;var motion=drive?motors[p].LastMotion:new Pvp.Rules.PvpMotionTrace{Tick=tick};law.Observe(p,before[p],after,motion,current,a.Round.CanComplete);a.ObserveVehicle(p,after,true);if(command.HasValue)a.Enqueue(p,command.Value);
   }a.Advance(tick);if(tick%5==0){world=a.Snapshot();shared=current;}if(tick%1000==0)Debug.Log("PVP_SERVICE_TRIP_TRACE tick="+tick+" completed="+world.Scores[0].Completed+" pose="+JsonUtility.ToJson(motors[0].Capture())+" service="+JsonUtility.ToJson(world.Services[0]));
  }Debug.Log("PVP_SERVICE_TRIP_END done="+done+" cancel="+cancel+" fuel="+world.Services[0].Fuel+" expenses="+world.Scores[0].ServiceExpenses+" last="+JsonUtility.ToJson(world.Responses[0]));Check(done&&cancel&&world.Scores[0].ServiceExpenses==2,"continuous input passenger to service");Debug.Log("PVP_SERVICE_TRIP_OK");
 }finally{UnityEngine.Object.DestroyImmediate(d);}}
}}
